def hydrate_time(nanoseconds, tz=None):
    """
    Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds: Number of nanoseconds since midnight (int, float, or convertible to int).
    :param tz: Optional timezone information. Can be a datetime.tzinfo instance, an integer/float offset in seconds,
               or a string in the format '+HH:MM' or '-HH:MM'.
    :return: datetime.time instance representing the time of day.
    """
    import datetime

    # Validate and convert nanoseconds to integer
    try:
        ns = int(nanoseconds)
    except Exception as exc:
        raise TypeError("nanoseconds must be an integer or convertible to int") from exc

    # Normalize to a value within a single day (0 <= ns < 24h in nanoseconds)
    ns_per_day = 24 * 3600 * 1_000_000_000
    ns = ns % ns_per_day

    # Break down into hours, minutes, seconds, and microseconds
    total_seconds, rem_ns = divmod(ns, 1_000_000_000)
    hour, rem = divmod(total_seconds, 3600)
    minute, second = divmod(rem, 60)
    microsecond = rem_ns // 1000  # datetime.time only supports microseconds

    # Resolve timezone information
    tzinfo = None
    if tz is not None:
        if isinstance(tz, datetime.tzinfo):
            tzinfo = tz
        elif isinstance(tz, (int, float)):
            # Treat numeric tz as offset in seconds
            tzinfo = datetime.timezone(datetime.timedelta(seconds=tz))
        elif isinstance(tz, str):
            # Expect format '+HH:MM' or '-HH:MM'
            try:
                if tz[0] in ('+', '-'):
                    sign = 1 if tz[0] == '+' else -1
                    parts = tz[1:].split(':')
                    if len(parts) == 2:
                        hours_offset = int(parts[0])
                        minutes_offset = int(parts[1])
                        offset_seconds = sign * (hours_offset * 3600 + minutes_offset * 60)
                        tzinfo = datetime.timezone(datetime.timedelta(seconds=offset_seconds))
                    else:
                        raise ValueError
                else:
                    raise ValueError
            except Exception as exc:
                raise ValueError(f"Invalid tz string format: {tz}") from exc
        else:
            raise TypeError("tz must be None, a tzinfo instance, an int/float offset, or a '+HH:MM'/'-HH:MM' string")

    # Construct and return the time object
    try:
        return datetime.time(hour, minute, second, microsecond, tzinfo=tzinfo)
    except Exception as exc:
        raise ValueError(f"Failed to create time object: {exc}") from exc

def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    # Allow None to be passed through unchanged
    if value is None:
        return None
    # Attempt to convert the time-like object to an ISO formatted string
    try:
        return value.isoformat()
    except AttributeError:
        # The object does not have an isoformat method – not a time-like object
        raise TypeError(
            f"Expected a time-like object with an 'isoformat' method, got {type(value).__name__}"
        )
    except Exception as exc:
        # Any other exception is wrapped in a ValueError for clarity
        raise ValueError(f"Failed to dehydrate time value: {exc}") from exc

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    # Guard against a None instance (unlikely but defensive)
    if self is None:
        raise TypeError("keys() called on None")

    try:
        # If the object stores data in a known attribute
        for attr in ('data', 'record', 'dict', 'items'):
            if hasattr(self, attr):
                value = getattr(self, attr)
                # If it's a dict, return its keys
                if isinstance(value, dict):
                    return list(value.keys())
                # If it's an items method, use it to extract keys
                if callable(value):
                    try:
                        return [k for k, _ in value()]
                    except Exception:
                        pass

        # If the instance itself behaves like a dict
        if isinstance(self, dict):
            return list(dict.keys(self))

        # Fallback: use the instance's __dict__ but filter out private/internal attributes
        return [k for k in getattr(self, "__dict__", {}) if not k.startswith("_")]

    except Exception as exc:
        raise RuntimeError(f"Unable to retrieve keys from {self!r}: {exc}") from exc

def unit_of_work(metadata=None, timeout=None):
    """
    Decorator for transaction functions that allows extra control over how the transaction is carried out.
    """
    # Validate metadata
    if metadata is not None and not isinstance(metadata, dict):
        raise TypeError("metadata must be a dict or None")
    # Validate timeout
    if timeout is not None:
        if not isinstance(timeout, (int, float)):
            raise TypeError("timeout must be a number or None")
        if timeout < 0:
            raise ValueError("timeout must be non-negative")
    def decorator(func):
        def wrapper(tx, *args, **kwargs):
            if tx is None:
                raise ValueError("transaction object (tx) cannot be None")
            # Apply metadata if provided
            if metadata is not None:
                # Some transaction objects may not support set_metadata; ignore if not present
                if hasattr(tx, "set_metadata"):
                    try:
                        tx.set_metadata(metadata)
                    except Exception:
                        # If setting metadata fails, propagate the exception
                        raise
            # Apply timeout if provided
            if timeout is not None:
                if hasattr(tx, "set_timeout"):
                    try:
                        tx.set_timeout(timeout)
                    except Exception:
                        raise
            return func(tx, *args, **kwargs)
        # Preserve function metadata
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__dict__.update(func.__dict__)
        return wrapper
    return decorator

def index(self, key):
    """Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        # Attempt to locate the underlying data container
        data = getattr(self, "_data", None)
        if data is None:
            data = getattr(self, "data", None)
        if data is None:
            raise AttributeError("Container has no data attribute")

        # If the data is a dictionary, search in its keys
        if isinstance(data, dict):
            if key in data:
                return list(data.keys()).index(key)
            raise ValueError(f"{key!r} is not in container")

        # Otherwise, assume the data is an iterable (e.g., list, tuple)
        for idx, item in enumerate(data):
            if item == key:
                return idx

        # If we get here, the key was not found
        raise ValueError(f"{key!r} is not in container")

    except TypeError:
        raise TypeError("Container data is not iterable")
    except AttributeError as e:
        raise AttributeError(str(e))

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Attempt to retrieve all values from the record
    try:
        all_values = list(self.values())
    except AttributeError as e:
        raise TypeError("The object does not support a 'values()' method") from e

    # If no keys are provided, return all values
    if not keys:
        return all_values

    result = []
    for key in keys:
        # Treat integers as positional indexes
        if isinstance(key, int):
            try:
                result.append(all_values[key])
            except IndexError as e:
                raise IndexError(f"Index {key} is out of range") from e
        else:
            # Treat other types as dictionary keys
            try:
                result.append(self[key])
            except KeyError as e:
                raise KeyError(f"Key {key!r} not found in the record") from e
            except TypeError as e:
                # Key is not hashable
                raise TypeError(f"Key {key!r} is not hashable") from e
    return result

