    """
    # Validate numeric arguments
    if not isinstance(n, int):
        raise TypeError(f"n must be an int, got {type(n).__name__}")
    if not isinstance(qid, int):
        raise TypeError(f"qid must be an int, got {type(qid).__name__}")
    if n < -1:
        raise ValueError("n must be -1 (ALL) or a non‑negative integer")
    if qid < -1:
        raise ValueError("qid must be -1 (last query) or a non‑negative integer")

    # Validate hooks
    for hooks, name in ((dehydration_hooks, "dehydration_hooks"),
                        (hydration_hooks, "hydration_hooks")):
        if hooks is not None:
            if not isinstance(hooks, dict):
                raise TypeError(f"{name} must be a dict or None, got {type(hooks).__name__}")
            for key, func in hooks.items():
                if not isinstance(key, type):
                    raise TypeError(f"Key {key!r} in {name} is not a type")
                if not callable(func):
                    raise TypeError(f"Value for type {key!r} in {name} is not callable")

    # Build the DISCARD message
    message = {"type": "DISCARD", "n": n, "qid": qid}

    # Append to the output queue
    try:
        self._output_queue.append(message)
    except AttributeError as exc:
        raise AttributeError("Output queue not initialized on this instance") from exc

    # Construct and return a Response object
    # The Response constructor is assumed to accept the message and optional hooks/handlers
    return Response(message=message,
                    dehydration_hooks=dehydration_hooks,
                    hydration_hooks=hydration_hooks,
                    **handlers)

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
          db=None, imp_user=None, dehydration_hooks=None,
          hydration_hooks=None, **handlers):
    """
    Appends a BEGIN message to the output queue.

    :param mode: access mode for routing - "READ" or "WRITE" (default)
    :param bookmarks: iterable of bookmark values after which this transaction should begin
    :param metadata: custom metadata dictionary to attach to the transaction
    :param timeout: timeout for transaction execution (seconds)
    :param db: name of the database against which to begin the transaction
        Requires Bolt 4.0+.
    :param imp_user: the user to impersonate
        Requires Bolt 4.4+
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    :return: Response object
    """
    # Validate mode
    if mode is not None and mode not in ("READ", "WRITE"):
        raise ValueError(f"Invalid mode: {mode!r}. Expected 'READ' or 'WRITE'.")

    # Validate bookmarks
    if bookmarks is not None:
        try:
            bookmarks = list(bookmarks)
        except TypeError:
            raise TypeError("bookmarks must be an iterable of bookmark strings.")
        for bm in bookmarks:
            if not isinstance(bm, str):
                raise TypeError("Each bookmark must be a string.")

    # Validate metadata
    if metadata is not None and not isinstance(metadata, dict):
        raise TypeError("metadata must be a dict.")

    # Validate timeout
    if timeout is not None:
        if not isinstance(timeout, (int, float)):
            raise TypeError("timeout must be a number.")
        if timeout < 0:
            raise ValueError("timeout must be non-negative.")

    # Validate db and imp_user
    if db is not None and not isinstance(db, str):
        raise TypeError("db must be a string.")
    if imp_user is not None and not isinstance(imp_user, str):
        raise TypeError("imp_user must be a string.")

    # Validate hooks
    for hooks, name in [(dehydration_hooks, "dehydration_hooks"),
                        (hydration_hooks, "hydration_hooks")]:
        if hooks is not None:
            if not isinstance(hooks, dict):
                raise TypeError(f"{name} must be a dict mapping type to callable.")
            for key, func in hooks.items():
                if not isinstance(key, type):
                    raise TypeError(f"Key {key!r} in {name} must be a type.")
                if not callable(func):
                    raise TypeError(f"Value for {key!r} in {name} must be callable.")

    # Build the BEGIN message
    message = {"type": "BEGIN"}
    if mode is not None:
        message["mode"] = mode
    if bookmarks is not None:
        message["bookmarks"] = bookmarks
    if metadata is not None:
        message["metadata"] = metadata
    if timeout is not None:
        message["timeout"] = timeout
    if db is not None:
        message["db"] = db
    if imp_user is not None:
        message["imp_user"] = imp_user
    if dehydration_hooks is not None:
        message["dehydration_hooks"] = dehydration_hooks
    if hydration_hooks is not None:
        message["hydration_hooks"] = hydration_hooks

    # Append to the output queue
    try:
        self._output_queue.append(message)
    except AttributeError:
        raise RuntimeError("Output queue not initialized or not writable.")

    # Return a Response object with the provided handlers
    return Response(**handlers)

def deprecated(message):
    """Decorator for deprecating functions and methods.

    Usage:

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass
    """
    if not isinstance(message, str):
        raise TypeError("message must be a string")
    import warnings
    import functools

    def decorator(func):
        if not callable(func):
            raise TypeError("deprecated decorator can only be applied to callable objects")
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper

    return decorator

def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""
    # Validate input
    if seq is None:
        raise TypeError("seq must not be None")
    if not isinstance(seq, Sequence):
        raise TypeError("seq must be a Sequence")
    for i, item in enumerate(seq):
        if not isinstance(item, str):
            raise TypeError(f"All elements of seq must be str, element at index {i} is {type(item).__name__}")
    items = list(seq)
    try:
        import hashlib, random
        # Create a stable seed from the content
        seed_input = '\0'.join(items)
        seed_hash = hashlib.sha256(seed_input.encode('utf-8')).hexdigest()
        seed = int(seed_hash, 16) % (2**32)
        rng = random.Random(seed)
        rng.shuffle(items)
    except Exception as e:
        raise RuntimeError(f"Error during deterministic shuffle: {e}") from e
    return items

