@classmethod
def _reset_logging(cls):
    """
    Reset logging configuration to default state.
    """
    # Attempt to obtain the logging module from the current globals.
    try:
        logging = globals().get('logging')
        if logging is None:
            raise RuntimeError("Logging module not available")
        root = logging.getLogger()
    except Exception as e:
        raise RuntimeError("Failed to access logging module") from e

    # Remove all handlers and reset the root logger's level.
    try:
        for handler in root.handlers[:]:
            try:
                handler.close()

def _getTargetClass(self):
        """
        Define this to return the implementation in use,
        without the 'Py' or 'Fallback' suffix.
        """
        try:
            cls_name = self.__class__.__name__
        except Exception:
            return None
        # Strip 'Fallback' suffix if present
        if cls_name.endswith('Fallback'):
            return cls_name[:-len('Fallback')]
        # Strip 'Py' suffix if present
        if cls_name.endswith('Py'):
            return cls_name[:-len('Py')]
        return cls_name

def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """
    # Validate input
    if not isinstance(orderings, (list, tuple)):
        raise TypeError("orderings must be a list or tuple of iterables")
    # Build graph
    adjacency = {}
    indegree = {}
    # Record first appearance order
    first_index = {}
    idx_counter = 0
    for ordering in orderings:
        if not isinstance(ordering, (list, tuple)):
            raise TypeError("each ordering must be a list or tuple")
        for elem in ordering:
            if elem not in indegree:
                indegree[elem] = 0
                adjacency[elem] = set()
            if elem not in first_index:
                first_index[elem] = idx_counter
                idx_counter += 1
    # Add edges
    for ordering in orderings:
        for a, b in zip(ordering, ordering[1:]):
            if b not in adjacency[a]:
                adjacency[a].add(b)
                indegree[b] += 1
    # Kahn's algorithm with deterministic ordering
    import heapq
    zero_heap = []
    for node, deg in indegree.items():
        if deg == 0:
            heapq.heappush(zero_heap, (first_index[node], node))
    result = []
    while zero_heap:
        _, node = heapq.heappop(zero_heap)
        result.append(node)
        for succ in adjacency[node]:
            indegree[succ] -= 1
            if indegree[succ] == 0:
                heapq.heappush(zero_heap, (first_index[succ], succ))
    if len(result) != len(indegree):
        raise ValueError("orderings contain a cycle or inconsistent constraints")
    return result

