def _c_optimizations_required():
    """
    Return a true value if the C optimizations are required.

    This uses the ``PURE_PYTHON`` variable as documented in `_use_c_impl`.
    """
    try:
        return not bool(PURE_PYTHON)
    except NameError:
        # If PURE_PYTHON is not defined, assume C optimizations are required
        return True

def reset(self):
        """Reset the histogram.

        Current context is reset to an empty dict.
        Bins are reinitialized with the *initial_value*
        or with *make_bins()* (depending on the initialization).
        """
        try:
            # Reset context
            self._context = {}

            # Reinitialize bins
            if self._initial_value is not None:
                # Preserve the current number of bins if they exist
                if self._bins is None:
                    self._bins = []
                else:
                    self._bins = [self._initial_value] * len(self._bins)
            elif callable(self._make_bins):
                self._bins = self._make_bins()
            else:
                raise ValueError(
                    "Cannot reset histogram: no initial_value or make_bins callable provided."
                )
        except Exception as exc:
            raise RuntimeError(f"Failed to reset histogram: {exc}") from exc

def to_csv(self, separator=",", header=None):
        """
        Convert graph's points to CSV.

        *separator* delimits values, the default is comma.

        *header*, if not ``None``, is the first string of the output
        (new line is added automatically).

        Since a graph can be multidimensional,
        for each point first its coordinate is converted to string
        (separated by *separator*), then each part of its value.
        """
        # Validate separator
        if not isinstance(separator, str):
            raise TypeError("separator must be a string")
        # Validate header
        if header is not None and not isinstance(header, str):
            raise TypeError("header must be a string or None")

        lines = []

        # Add header if provided
        if header is not None:
            lines.append(header)

        # Ensure the object is iterable
        try:
            iterator = iter(self)
        except TypeError:
            raise TypeError("Graph object is not iterable")

        for point in iterator:
            # Each point is expected to be a tuple (coordinate, value)
            try:
                coord, val = point
            except Exception:
                # If point is not a 2-tuple, treat the whole point as coordinate
                coord = point
                val = None

            # Convert coordinate to string parts
            if isinstance(coord, (list, tuple)):
                coord_parts = [str(c) for c in coord]
            else:
                coord_parts = [str(coord)]

            # Convert value to string parts
            if val is None:
                val_parts = []
            elif isinstance(val, (list, tuple)):
                val_parts = [str(v) for v in val]
            else:
                val_parts = [str(val)]

            # Join coordinate and value parts
            line = separator.join(coord_parts + val_parts)
            lines.append(line)

        return "\n".join(lines)

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Validate input type
    if not isinstance(coord_name, str):
        raise TypeError("coord_name must be a string")

    # Ensure the attribute exists and is a dictionary
    if not hasattr(self, "_err_indices"):
        raise AttributeError("The object does not have an '_err_indices' attribute")
    err_dict = getattr(self, "_err_indices")
    if not isinstance(err_dict, dict):
        raise TypeError("The '_err_indices' attribute must be a dictionary")

    # Retrieve indices for the given coordinate name
    indices = err_dict.get(coord_name)

    # If no indices are found, return an empty list
    if indices is None:
        return []

    # Convert the indices to a list for consistency
    if hasattr(indices, "tolist"):
        # Handles numpy arrays or pandas Series
        return indices.tolist()
    try:
        return list(indices)
    except TypeError:
        # If indices is a single value, wrap it in a list
        return [indices]

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Validate inputs
    try:
        bins_list = list(bins)
        edges_list = list(edges)
    except TypeError:
        raise TypeError("bins and edges must be iterable")

    if not edges_list:
        raise ValueError("edges must not be empty")

    if len(edges_list) != len(bins_list) + 1:
        raise ValueError("edges length must be one more than bins length")

    total = 0.0
    for i, bin_val in enumerate(bins_list):
        try:
            width = edges_list[i + 1] - edges_list[i]
        except Exception as exc:
            raise TypeError(f"Could not compute width for bin {i}: {exc}") from exc
        try:
            total += bin_val * width
        except Exception as exc:
            raise TypeError(f"Could not multiply bin value and width for bin {i}: {exc}") from exc

    return total

def is_fill_request_el(obj):
