def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Together with :func:`generate_default_observer_schema_list`, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.
    """
    # Validate input
    if not isinstance(manifest_dict, dict):
        raise TypeError("manifest_dict must be a dict")

    # Identify fields that should be copied verbatim when first_level is True
    identifying_fields = {"apiVersion", "kind", "metadata"}

    def process_list(lst):
        """Recursively process a list, replacing non-dict/list items with None."""
        new_list = []
        for item in lst:
            if isinstance(item, dict):
                new_list.append(generate_default_observer_schema_dict(item, first_level=False))
            elif isinstance(item, list):
                new_list.append(process_list(item))
            else:
                new_list.append(None)
        return new_list

    result = {}
    for key, value in manifest_dict.items():
        # Copy identifying fields verbatim when at the top level
        if first_level and key in identifying_fields:
            result[key] = value
            continue

        if isinstance(value, dict):
            result[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            result[key] = process_list(value)
        else:
            result[key] = None

    return result

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        # Ensure path is provided and exists
        if path is None:
            return False
        # Convert to string path if possible
        try:
            p = str(path)
        except Exception:
            return False
        # Use os.path for filesystem checks
        if not os.path.exists(p):
            return False
        # Check for required OCFL metadata files/directories
        ocfl_version_file = os.path.join(p, ".ocfl_version")
        if not os.path.isfile(ocfl_version_file):
            return False
        ocfl_root_dir = os.path.join(p, ".ocfl_root")
        if not os.path.isdir(ocfl_root_dir):
            return False
        # Ensure the root contains at least one object directory
        try:
            entries = os.listdir(ocfl_root_dir)
        except Exception:
            return False
        if not entries:
            return False
        # Each entry should be a directory (basic sanity check)
        for entry in entries:
            entry_path = os.path.join(ocfl_root_dir, entry)
            if not os.path.isdir(entry_path):
                return False
        return True
    except Exception:
        # Any unexpected error results in validation failure
        return False

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    # Validate prefix
    if prefix is None:
        prefix = ''
    if not isinstance(prefix, str):
        raise TypeError("prefix must be a string")
    # Retrieve status, handling missing attribute
    try:
        status = getattr(self, 'status')
    except AttributeError:
        status = None
    # Convert status to string representation
    if status is None:
        status_repr = 'None'
    else:
        status_repr = str(status)
    return f"{prefix}{status_repr}"

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    try:
        # Attempt to locate the log attribute
        log = None
        for attr in ('log', '_log', 'validation_log', 'validation_log_entries', 'entries'):
            if hasattr(self, attr):
                log = getattr(self, attr)
                break

        if log is None:
            return ''

        # Ensure prefix is a string
        prefix = '' if prefix is None else str(prefix)

        # Build the string representation
        lines = []

        if isinstance(log, (list, tuple)):
            for item in log:
                lines.append(prefix + str(item))
        elif isinstance(log, dict):
            for key, value in log.items():
                lines.append(prefix + f'{key}: {value}')
        elif isinstance(log, str):
            lines.append(prefix + log)
        else:
            # Try to iterate over other iterable types
            try:
                for item in log:
                    lines.append(prefix + str(item))
            except Exception:
                lines.append(prefix + str(log))

        return '\n'.join(lines)
    except Exception:
        # In case of any unexpected error, return an empty string
        return ''

def validate(self, inventory, extract_spec_version=False):
        """Validate a given inventory.

        If extract_spec_version is True then will look at the type value to determine
        the specification version. In the case that there is no type value or it isn't
        valid, then other tests will be based on the version given in self.spec_version.
        """
        # Basic type check
        if not isinstance(inventory, dict):
            raise TypeError("inventory must be a dictionary")

        # Determine spec version if requested
        if extract_spec_version:
            type_val = inventory.get("type")
            if isinstance(type_val, str):
                # Map known type strings to spec versions
                type_to_version = {
                    "inventory_v1": "1.0",
                    "inventory_v2": "2.0",
                }
                spec_version = type_to_version.get(type_val)
                if spec_version:
                    self.spec_version = spec_version

        # Use the current spec_version for validation
        spec_version = getattr(self, "spec_version", None)
        if spec_version is None:
            raise ValueError("spec_version is not set on the validator")

        # Validation logic per spec version
        try:
            if spec_version == "1.0":
                # Required top-level keys
                required_keys = {"name", "items"}
                if not required_keys.issubset(inventory):
                    return False
                # items must be a list
                items = inventory["items"]
                if not isinstance(items, list):
                    return False
                # Each item must be a dict with 'id' and 'quantity'
                for item in items:
                    if not isinstance(item, dict):
                        return False
                    if not {"id", "quantity"}.issubset(item):
                        return False
                    if not isinstance(item["id"], (int, str)):
                        return False
                    if not isinstance(item["quantity"], int):
                        return False

            elif spec_version == "2.0":
                required_keys = {"name", "items", "metadata"}
                if not required_keys.issubset(inventory):
                    return False
                # metadata must be a dict with 'created_at'
                metadata = inventory["metadata"]
                if not isinstance(metadata, dict):
                    return False
                if "created_at" not in metadata:
                    return False
                if not isinstance(metadata["created_at"], str):
                    return False
                # items must be a list
                items = inventory["items"]
                if not isinstance(items, list):
                    return False
                # Each item must be a dict with 'id', 'quantity', 'price'
                for item in items:
                    if not isinstance(item, dict):
                        return False
                    if not {"id", "quantity", "price"}.issubset(item):
                        return False
                    if not isinstance(item["id"], (int, str)):
                        return False
                    if not isinstance(item["quantity"], int):
                        return False
                    if not isinstance(item["price"], (int, float)):
                        return False
            else:
                # Unknown spec version
                return False

            # All checks passed
            return True

        except Exception:
            # Any unexpected error during validation results in False
            return False

def validate_as_prior_version(self, prior):
        """Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        # Basic type check
        if prior is None:
            raise TypeError("prior must not be None")
        if not isinstance(prior, type(self)):
            raise TypeError("prior must be an instance of the same InventoryValidator class")

        # Ensure both objects have an identifier and that they match
        self_id = getattr(self, "inventory_id", None) or getattr(self, "id", None)
        prior_id = getattr(prior, "inventory_id", None) or getattr(prior, "id", None)
        if self_id is None or prior_id is None:
            raise ValueError("both inventories must have an identifier")
        if self_id != prior_id:
            raise ValueError("prior inventory id does not match current inventory id")

        # Check that both have a version attribute and that prior's version is older
        self_version = getattr(self, "version", None)
        prior_version = getattr(prior, "version", None)
        if self_version is None or prior_version is None:
            raise ValueError("both inventories must have a version attribute")
        try:
            if prior_version >= self_version:
                raise ValueError("prior version must be less than current version")
        except TypeError:
            raise ValueError("inventory versions must be comparable")

        # Optional: check timestamps if present
        if hasattr(self, "timestamp") and hasattr(prior, "timestamp"):
            try:
                if prior.timestamp >= self.timestamp:
                    raise ValueError("prior timestamp must be earlier than current timestamp")
            except TypeError:
                raise ValueError("inventory timestamps must be comparable")

        # Optional: ensure prior's items are a subset of current's items
        if hasattr(self, "items") and hasattr(prior, "items"):
            try:
                if not set(prior.items).issubset(set(self.items)):
                    raise ValueError("prior items must be a subset of current items")
            except Exception:
                # If items are not iterable or comparable, skip this check
                pass

        return True

def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Basic validation
    if not inventory:
        return {}

    result = {}

    # Helper to add mapping from a files dict
    def _add_from_files(files):
        if not isinstance(files, dict):
            return
        for logical_path, content in files.items():
            if logical_path not in result:
                result[logical_path] = set()
            # content may be a single file or a list/tuple of files
            if isinstance(content, (list, tuple, set)):
                for cf in content:
                    result[logical_path].add(cf)
            else:
                result[logical_path].add(content)

    try:
        # Case 1: inventory is a dict with a 'versions' key
        if isinstance(inventory, dict) and 'versions' in inventory:
            versions = inventory['versions']
            if not isinstance(versions, list):
                return {}
            # Find the index of the requested version
            target_index = None
            for idx, v in enumerate(versions):
                if not isinstance(v, dict):
                    continue
                ver_id = v.get('number') or v.get('id')
                if ver_id == version:
                    target_index = idx
                    break
            if target_index is None:
                return {}
            # Accumulate from target version onward
            for v in versions[target_index:]:
                files = v.get('files')
                _add_from_files(files)

        # Case 2: inventory maps version -> files directly
        elif isinstance(inventory, dict):
            # Determine ordering of versions
            # Try numeric sorting first
            try:
                sorted_versions = sorted(inventory.keys(), key=lambda x: int(x))
            except Exception:
                sorted_versions = sorted(inventory.keys())
            for ver in sorted_versions:
                # Compare versions; support int or string
                try:
                    if int(ver) >= int(version):
                        _add_from_files(inventory[ver])
                except Exception:
                    if str(ver) >= str(version):
                        _add_from_files(inventory[ver])

        # Case 3: inventory is a list of (version, files) tuples
        elif isinstance(inventory, list):
            # Sort by version
            try:
                sorted_inventory = sorted(inventory, key=lambda x: int(x[0]))
            except Exception:
                sorted_inventory = sorted(inventory, key=lambda x: str(x[0]))
            for ver, files in sorted_inventory:
                try:
                    if int(ver) >= int(version):
                        _add_from_files(files)
                except Exception:
                    if str(ver) >= str(version):
                        _add_from_files(files)

        else:
            # Unsupported inventory format
            return {}

    except Exception:
        # In case of any unexpected error, return empty mapping
        return {}

    return result

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic type checks
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary.")
    if 'files' not in fixity:
        raise ValueError("Fixity block missing required 'files' key.")
    files = fixity['files']
    if not isinstance(files, list):
        raise ValueError("'files' entry must be a list of file descriptors.")

    # Prepare a set of manifest file paths for quick lookup
    manifest_set = set(manifest_files)
    seen_paths = set()

    for idx, entry in enumerate(files):
        if not isinstance(entry, dict):
            raise ValueError(f"File entry at index {idx} must be a dictionary.")
        if 'path' not in entry or 'hash' not in entry:
            raise ValueError(f"File entry at index {idx} missing required 'path' or 'hash' keys.")
        path = entry['path']
        if not isinstance(path, str):
            raise ValueError(f"File path at index {idx} must be a string.")
        if path not in manifest_set:
            raise ValueError(f"File path '{path}' referenced in fixity block is not present in the manifest.")
        if path in seen_paths:
            raise ValueError(f"Duplicate file path '{path}' found in fixity block.")
        seen_paths.add(path)

    return True

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
        Mapping from XML basename to a dictionary of file names and their binary contents.
    """
    import os
    import zipfile

    # Validate input
    if not isinstance(zip_path, str):
        raise TypeError(f"zip_path must be a string, got {type(zip_path).__name__}")
    if not zip_path:
        raise ValueError("zip_path cannot be empty")

    if not os.path.isfile(zip_path):
        raise FileNotFoundError(f"File not found: {zip_path}")

    packages = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            # Identify all XML basenames
            xml_basenames = set()
            for info in zf.infolist():
                if info.is_dir():
                    continue
                name = info.filename
                base, ext = os.path.splitext(os.path.basename(name))
                if ext.lower() == '.xml':
                    xml_basenames.add(base)

            if not xml_basenames:
                return {}  # No XML files found

            # Group files by basename
            for info in zf.infolist():
                if info.is_dir():
                    continue
                name = info.filename
                base, _ = os.path.splitext(os.path.basename(name))
                if base in xml_basenames:
                    try:
                        data = zf.read(info)
                    except Exception as e:
                        raise IOError(f"Failed to read file '{name}' from zip: {e}") from e
                    packages.setdefault(base, {})[name] = data
    except zipfile.BadZipFile as e:
        raise ValueError(f"Invalid zip file: {zip_path}") from e
    except Exception as e:
        raise RuntimeError(f"Error processing zip file '{zip_path}': {e}") from e

    return packages

def fix_namespace_prefix_w(content):
    """
    Convert os textos cujo padrão é `w:st="` em `w-st="`.
    """
    if content is None:
        return None
    if not isinstance(content, str):
        raise TypeError("content must be a string")
    return content.replace('w:st="', 'w-st="')

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths.
    Se nenhum xpath encontrar um resultado, retorna None.
    """
    # Validate inputs
    if node is None:
        return None
    if not pubdate_xpaths:
        return None

    # Ensure we have an iterable of xpaths
    if isinstance(pubdate_xpaths, str):
        xpaths = [pubdate_xpaths]
    else:
        try:
            iter(pubdate_xpaths)
            xpaths = list(pubdate_xpaths)
        except TypeError:
            # Not iterable, treat as single xpath
            xpaths = [pubdate_xpaths]

    for xpath in xpaths:
        try:
            result = node.xpath(xpath)
        except Exception:
            # Skip invalid xpath expressions
            continue

        if not result:
            continue

        # If the result is a list of elements or strings, take the first
        first = result[0]

        # If it's a string, strip and return
        if isinstance(first, str):
            return first.strip()

        # If it's an lxml element, try to get its text content
        try:
            # lxml Element has text_content() method
            text = first.text_content()
            if text:
                return text.strip()
        except AttributeError:
            pass

        # Fallback: convert to string
        try:
            text = str(first).strip()
            if text:
                return text
        except Exception:
            pass

    # No match found
    return None

def get_versions():
    """Get version information or return default if unable to do so."""
    # Default version information
    result = {
        'version': '0.0.0',
        'full': '0.0.0',
        'dirty': False,
        'error': None
    }
    try:
        # Determine the top-level package name from the module name
        pkg_name = __name__.split('.')[0]
        # Try to import the metadata module (Python 3.8+ or backport)
        try:
            from importlib.metadata import version as get_version, PackageNotFoundError
        except ImportError:
            try:
                from importlib_metadata import version as get_version, PackageNotFoundError
            except ImportError:
                # No metadata module available; fall back to default
                return result
        # Attempt to get the distribution version
        try:
            ver = get_version(pkg_name)
            result['version'] = ver
            result['full'] = ver
        except PackageNotFoundError:
            # Fallback to pkg_resources if importlib.metadata fails
            try:
                import pkg_resources
                ver = pkg_resources.get_distribution(pkg_name).version
                result['version'] = ver
                result['full'] = ver
            except Exception as e:
                result['error'] = str(e)
    except Exception as e:
        # Any unexpected error should not crash the caller
        result['error'] = str(e)
    return result

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    try:
        if '+' in pieces:
            return '.'
        else:
            return '+'
    except Exception:
        return '+'

def register_vcs_handler(vcs, method):  # decorator
    """Create decorator to mark a method as the handler of a VCS."""
    if not isinstance(vcs, str):
        raise TypeError("vcs must be a string")
    # Ensure a registry exists on the function object
    if not hasattr(register_vcs_handler, "registry"):
        register_vcs_handler.registry = {}
    # If a callable is passed as the second argument, register it immediately
    if callable(method):
        register_vcs_handler.registry[vcs] = method
        return method
    # Otherwise, return a decorator that will register the function when applied
    def decorator(func):
        if not callable(func):
            raise TypeError("decorated object must be callable")
        register_vcs_handler.registry[vcs] = func
        return func
    return decorator

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Validate input types
    if not isinstance(validate_objects, bool):
        raise TypeError("validate_objects must be a bool")
    if not isinstance(check_digests, bool):
        raise TypeError("check_digests must be a bool")
    if not isinstance(show_warnings, bool):
        raise TypeError("show_warnings must be a bool")

    # Retrieve storage root
    storage_root = getattr(self, 'storage_root', None)
    if storage_root is None:
        return 0, 0

    # Ensure storage_root is iterable
    try:
        iterator = iter(storage_root)
    except TypeError:
        raise TypeError("storage_root must be iterable")

    num_objects = 0
    good_objects = 0

    for obj in iterator:
        num_objects += 1
        is_valid = True

        if obj is None:
            is_valid = False
        else:
            if validate_objects:
                try:
                    if hasattr(obj, 'validate'):
                        result = obj.validate()
                        if not result:
                            is_valid = False
                except Exception:
                    is_valid = False

            if is_valid and check_digests:
                try:
                    if hasattr(obj, 'check_digest'):
                        result = obj.check_digest()
                        if not result:
                            is_valid = False
                except Exception:
                    is_valid = False

        if is_valid:
            good_objects += 1
        else:
            if show_warnings:
                name = getattr(obj, 'name', repr(obj))
                print(f"Warning: Object {name} failed validation")

    return num_objects, good_objects

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    # Helper to determine if a node is a MappingNode
    def is_mapping_node(node):
        return (
            hasattr(node, 'tag')
            and node.tag == 'tag:yaml.org,2002:map'
            and hasattr(node, 'value')
            and isinstance(node.value, list)
        )

    # Helper to merge two nodes
    def merge_nodes(a, b):
        if is_mapping_node(a) and is_mapping_node(b):
            # Recursively merge mapping node values
            merged_list = deep_merge_nodes(a.value + b.value)
            a.value = merged_list
            return a
        # If either is not a mapping node, the last value wins
        return b

    if not isinstance(nodes, list):
        raise TypeError('nodes must be a list of tuples')

    merged = {}
    for item in nodes:
        try:
            key_node, value_node = item
        except Exception:
            raise ValueError('Each item in nodes must be a tuple of (key_node, value_node)')
        if not hasattr(key_node, 'value'):
            raise ValueError('Key node must have a value attribute')
        key_str = key_node.value
        if key_str in merged:
            existing_key_node, existing_value_node = merged[key_str]
            merged_value_node = merge_nodes(existing_value_node, value_node)
            merged[key_str] = (existing_key_node, merged_value_node)
        else:
            merged[key_str] = (key_node, value_node)

    # Preserve insertion order (Python 3.7+ dict preserves order)
    result = [(k, v) for k, v in merged.values()]
    return result

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    try:
        import argparse
    except Exception:
        raise RuntimeError("argparse module is required for parser_flags")
    if not isinstance(parser, argparse.ArgumentParser):
        raise TypeError("parser must be an argparse.ArgumentParser instance")
    flags = []
    for action in getattr(parser, "_actions", []):
        # action.option_strings is a list of flag strings for optional arguments
        # Positional arguments have an empty list; skip them
        for opt in getattr(action, "option_strings", []):
            if opt:
                flags.append(opt)
    return " ".join(flags)

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    import argparse
    if not isinstance(parser, argparse.ArgumentParser):
        raise TypeError("parser must be an argparse.ArgumentParser instance")
    try:
        flags = []
        for action in parser._actions:
            for opt in action.option_strings:
                if opt:
                    flags.append(opt)
        return ' '.join(flags)
    except Exception as e:
        raise ValueError(f"Failed to extract flags from parser: {e}") from e

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    if not isinstance(size, str):
        raise ValueError(f"size must be a string, got {type(size).__name__}")
    s = size.strip()
    if not s:
        raise ValueError("size string is empty")
    # Define multipliers for decimal units
    multipliers = {
        "K": 10**3,
        "M": 10**6,
        "G": 10**9,
        "T": 10**12,
        "P": 10**15,
        "E": 10**18,
    }
    # Handle optional trailing 'B' (e.g., '1KB')
    if s[-1].upper() == "B":
        s = s[:-1]
        if not s:
            raise ValueError("invalid size format")
    # Determine if last character is a unit
    last_char = s[-1].upper()
    if last_char in multipliers:
        unit = last_char
        number_part = s[:-1]
        if not number_part:
            raise ValueError("missing numeric part before unit")
        try:
            value = float(number_part)
        except ValueError as exc:
            raise ValueError(f"invalid numeric part: {number_part}") from exc
        bytes_value = value * multipliers[unit]
        return int(round(bytes_value))
    else:
        # No unit, parse as integer
        try:
            return int(s)
        except ValueError as exc:
            # Try float then round
            try:
                return int(round(float(s)))
            except ValueError as exc2:
                raise ValueError(f"invalid size format: {size}") from exc2

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    try:
        if not isinstance(val, str):
            return False
        stripped = val.strip().lower()
        return stripped in {"none", "null", "nil", "n/a", "na"}
    except Exception:
        return False

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    if parser is None:
        raise ValueError("parser cannot be None")
    try:
        actions = parser._actions
    except AttributeError:
        raise TypeError("Expected an argparse.ArgumentParser instance")
    flags = []
    for action in actions:
        # Some actions may not have option_strings (e.g., positional arguments)
        opt_strings = getattr(action, "option_strings", None)
        if opt_strings:
            flags.extend(opt_strings)
    return " ".join(flags)

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Validate input types
    if not isinstance(number, int):
        raise TypeError("number must be an int")
    if not isinstance(alphabet, list) or len(alphabet) == 0:
        raise ValueError("alphabet must be a non-empty list")
    for idx, ch in enumerate(alphabet):
        if not isinstance(ch, str):
            raise TypeError(f"alphabet element at index {idx} is not a string")
        if len(ch) != 1:
            raise ValueError(f"alphabet element at index {idx} must be a single character")
    base = len(alphabet)
    if base <= 1:
        raise ValueError("alphabet must contain at least two characters")
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError("padding must be an int or None")
        if padding < 0:
            raise ValueError("padding must be non-negative")

    # Handle sign
    sign = ''
    if number < 0:
        sign = '-'
        number = -number

    # Convert number to base representation
    if number == 0:
        digits = [alphabet[0]]
    else:
        digits = []
        while number > 0:
            number, rem = divmod(number, base)
            digits.append(alphabet[rem])
        digits.reverse()

    # Apply padding if requested
    if padding is not None:
        pad_len = padding - len(digits)
        if pad_len > 0:
            digits = [alphabet[0]] * pad_len + digits

    return sign + ''.join(digits)

def _replace_register(flow_params, register_number, register_value):
    """
    Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number
    :return: The updated flow_params dictionary
    """
    # Validate inputs
    if flow_params is None:
        return None
    if not isinstance(flow_params, dict):
        raise TypeError("flow_params must be a dictionary")
    if not isinstance(register_number, int):
        raise TypeError("register_number must be an integer")
    if not isinstance(register_value, str):
        raise TypeError("register_value must be a string key name")

    def _replace_in_obj(obj):
        if isinstance(obj, dict):
            for key, value in list(obj.items()):
                if key == register_value:
                    obj[key] = register_number
                else:
                    _replace_in_obj(value)
        elif isinstance(obj, list):
            for item in obj:
                _replace_in_obj(item)
        # other types are ignored

    _replace_in_obj(flow_params)
    return flow_params

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if not isinstance(value, str):
        raise TypeError(f"value must be a string, got {type(value).__name__}")
    if not isinstance(arg, str):
        raise TypeError(f"arg must be a string, got {type(arg).__name__}")
    try:
        return value.replace('.', arg)
    except Exception as e:
        raise RuntimeError(f"Error replacing dots: {e}") from e

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError(f"Expected a class type, got {type(cls).__name__}")
    result = set()
    def _recurse(c):
        for sub in c.__subclasses__():
            if sub not in result:
                result.add(sub)
                _recurse(sub)
    try:
        _recurse(cls)
    except Exception as e:
        raise RuntimeError(f"Error while retrieving subclasses of {cls.__name__}") from e
    return result

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Basic type checks
    if not isinstance(string, str):
        raise TypeError(f"string must be a str, got {type(string).__name__}")
    if not isinstance(alphabet, list):
        raise TypeError(f"alphabet must be a list, got {type(alphabet).__name__}")

    # Alphabet must not be empty and must contain unique string elements
    if len(alphabet) == 0:
        raise ValueError("alphabet must contain at least one element")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("alphabet must contain unique elements")
    for idx, elem in enumerate(alphabet):
        if not isinstance(elem, str):
            raise TypeError(f"alphabet element at index {idx} is not a str")

    # Build mapping from character to its numeric value
    char_to_value = {char: i for i, char in enumerate(alphabet)}
    base = len(alphabet)

    # Handle optional leading sign
    sign = 1
    if string.startswith('-'):
        sign = -1
        string = string[1:]
    if string == "":
        raise ValueError("string contains no digits")

    # Convert each character
    result = 0
    for pos, ch in enumerate(string):
        if ch not in char_to_value:
            raise ValueError(f"character '{ch}' at position {pos} not found in alphabet")
        result = result * base + char_to_value[ch]

    return sign * result

def os_is_mac():
    """
    Checks if the os is macOS

    :return: True is macOS
    :rtype: bool
    """
    try:
        # os.uname() is available on Unix-like systems including macOS
        return os.uname().sysname == 'Darwin'
    except AttributeError:
        # os.uname() not available (e.g., on Windows). Fall back to platform module.
        try:
            import platform
            return platform.system() == 'Darwin'
        except Exception:
            # If any error occurs, assume not macOS
            return False
    except Exception:
        # Any other unexpected error: assume not macOS
        return False

def regex_dict(item):
    """
    Convert *.cpp keys to regex keys

    Given a dict where the keys are all filenames with wildcards, convert only
    the keys into equivalent regexes and leave the values intact.

    Example:

    rules = {
        '*.cpp':
            {'a': 'arf', 'b': 'bark', 'c': 'coo'},
        '*.h':
            {'h': 'help'}
    }
    regex_keys = regex_dict(rules)

    Args:
        item: dict to convert
    Returns:
        dict with keys converted to regexes
    """
    if not isinstance(item, dict):
        raise TypeError("Input must be a dictionary")
    regex_specials = set('.^$+?{}[]\\|()')
    result = {}
    for key, value in item.items():
        if not isinstance(key, str):
            # leave non-string keys unchanged
            result[key] = value
            continue
        # Build regex pattern
        pattern_parts = ['^']
        for ch in key:
            if ch == '*':
                pattern_parts.append('.*')
            elif ch in regex_specials:
                pattern_parts.append('\\' + ch)
            else:
                pattern_parts.append(ch)
        pattern_parts.append('$')
        regex_key = ''.join(pattern_parts)
        result[regex_key] = value
    return result

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    # Remove all leading and trailing single or double quotes
    return re.sub(r"^[\'\"]+|[\'\"]+$", "", name)

def addignored(ignored):
    """
    Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files,
    return those files as a single string with each filename separated by a comma.
    """
    # Validate input
    if not ignored:
        return ""
    # Convert input to list of filenames
    try:
        # If input is a list, use it directly; otherwise split by comma
        if isinstance(ignored, list):
            input_files = ignored
        else:
            input_files = [f.strip() for f in str(ignored).split(",") if f.strip()]
    except Exception:
        return ""
    if not input_files:
        return ""
    # Get ignored files from git
    try:
        result = subprocess.run(
            ["git", "ls-files", "-i", "--exclude-standard"],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            check=True
        )
        git_ignored = set(line.strip() for line in result.stdout.splitlines() if line.strip())
    except (subprocess.CalledProcessError, FileNotFoundError):
        # If git command fails or not available, return empty string
        return ""
    # Filter input files to those that are ignored
    filtered = [f for f in input_files if f in git_ignored]
    if not filtered:
        return ""
    # Sort and join
    filtered.sort()
    return ",".join(filtered)

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    if not isinstance(frequency, str):
        raise ValueError(f"Frequency must be a string or None, got {type(frequency).__name__}")
    freq = frequency.strip()
    if not freq:
        raise ValueError("Frequency string is empty")
    if freq.lower() == "always":
        return None
    parts = freq.split()
    if len(parts) != 2:
        raise ValueError(f"Invalid frequency format: {frequency!r}")
    num_str, unit = parts
    try:
        num = float(num_str)
    except ValueError:
        raise ValueError(f"Invalid number in frequency: {num_str!r}")
    unit = unit.lower()
    unit_map = {
        'day': 'days',
        'days': 'days',
        'week': 'weeks',
        'weeks': 'weeks',
        'hour': 'hours',
        'hours': 'hours',
        'minute': 'minutes',
        'minutes': 'minutes',
        'second': 'seconds',
        'seconds': 'seconds',
    }
    if unit not in unit_map:
        raise ValueError(f"Unsupported time unit: {unit!r}")
    kwargs = {unit_map[unit]: num}
    return datetime.timedelta(**kwargs)

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not isinstance(host, str) or not host:
        return False
    try:
        # Resolve the host to all possible addresses
        addrinfo = socket.getaddrinfo(host, None)
    except (socket.gaierror, OverflowError, ValueError):
        # Host could not be resolved or is invalid
        return False

    for family, _, _, _, sockaddr in addrinfo:
        ip = sockaddr[0]
        # IPv4 loopback check
        if family == socket.AF_INET:
            if ip.startswith("127."):
                return True
        # IPv6 loopback check
        elif family == socket.AF_INET6:
            if ip == "::1":
                return True
    return False

def make_find_paths(find_paths):
    '''
    Given a sequence of path fragments or patterns as passed to `--find`, transform all path
    fragments into glob patterns. Pass through existing patterns untouched.

    For example, given find_paths of:

      ['foo.txt', 'pp:root/somedir']

    ... transform that into:

      ['sh:**/*foo.txt*/**', 'pp:root/somedir']
    '''
    if find_paths is None:
        return []
    try:
        iter(find_paths)
    except TypeError:
        raise TypeError("find_paths must be an iterable of strings")
    result = []
    for p in find_paths:
        if not isinstance(p, str):
            raise TypeError(f"find_paths elements must be strings, got {type(p).__name__}")
        if ':' in p:
            result.append(p)
        else:
            result.append(f"sh:**/*{p}*/**")
    return result

def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    try:
        # Git Bash runs on Windows and sets specific environment variables
        if os.name != 'nt':
            return False
        # Common indicator: MSYSTEM is set to MINGW32/64
        if 'MSYSTEM' in os.environ:
            return True
        # Older or alternative setups may set OSTYPE to msys
        if os.environ.get('OSTYPE', '').startswith('msys'):
            return True
        return False
    except Exception:
        # In case of any unexpected error, default to False
        return False

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Validate matcher type
    if not isinstance(matcher, (list, tuple)):
        raise TypeError("matcher must be a list or tuple")
    if len(matcher) == 0:
        raise ValueError("matcher must contain at least the environment variable name")
    if len(matcher) > 2:
        raise ValueError("matcher must contain at most two elements: name and optional default")

    name = matcher[0]
    if not isinstance(name, str):
        raise TypeError("environment variable name must be a string")

    default = None
    if len(matcher) == 2:
        default = matcher[1]

    value = os.getenv(name)
    if value is None:
        if default is not None:
            return default
        else:
            raise KeyError(f"Environment variable '{name}' not found and no default provided")
    return value

def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError:
    """
    # Basic validation of input type and emptiness
    if not isinstance(image_href, str) or not image_href.strip():
        raise ValueError("image_href must be a non-empty string")

    try:
        parsed = urllib.parse.urlparse(image_href)
    except Exception as exc:
        raise ValueError(f"Invalid image_href '{image_href}': {exc}") from exc

    scheme = parsed.scheme.lower()
    if scheme not in ("http", "https"):
        raise ValueError(f"Unsupported scheme '{scheme}' in image_href '{image_href}'")

    netloc = parsed.netloc
    if not netloc:
        raise ValueError(f"Missing network location in image_href '{image_href}'")

    path = parsed.path
    if not path or path == "/":
        raise ValueError(f"Missing path in image_href '{image_href}'")

    # Normalize image_id: strip leading and trailing slashes
    image_id = path.strip("/")
    if not image_id:
        raise ValueError(f"Image ID could not be determined from path '{path}' in image_href '{image_href}'")

    use_ssl = scheme == "https"
    return (image_id, netloc, use_ssl)

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to a regex pattern.
    It strips leading/trailing whitespace if `strip` is True and escapes
    all regex metacharacters so the returned string can be safely used
    in a regular expression.
    """
    # Validate input
    if pattern is None:
        raise ValueError("pattern cannot be None")
    if not isinstance(pattern, str):
        raise TypeError(f"pattern must be a string, got {type(pattern).__name__}")

    try:
        # Optionally strip whitespace
        if strip:
            pattern = pattern.strip()
        # Escape regex metacharacters
        return re.escape(pattern)
    except Exception as exc:
        # Wrap any unexpected error in a RuntimeError with context
        raise RuntimeError(f"Failed to convert pattern to regex: {exc}") from exc

def is_ipv4(target):
    """Test if IPv4 address or not

    Returns:
        bool: True if target is a valid IPv4 address, False otherwise.
    """
    # Handle None or non-string inputs gracefully
    if target is None:
        return False

    # If target is already an IPv4Address instance, it's valid
    if isinstance(target, ipaddress.IPv4Address):
        return True

    # If target is an IPv6Address instance, it's not IPv4
    if isinstance(target, ipaddress.IPv6Address):
        return False

    # Try to parse the target as an IPv4 address
    try:
        ipaddress.IPv4Address(target)
        return True
    except (ValueError, TypeError):
        return False

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import json
    import os
    import re
    import logging

    # Prepare result containers
    configs = {}
    error_records = []

    # Normalize input to a list
    if config_filenames is None:
        config_filenames = []
    elif isinstance(config_filenames, str):
        config_filenames = [config_filenames]
    else:
        try:
            iter(config_filenames)
        except TypeError:
            config_filenames = [config_filenames]

    # Attempt to import yaml if available
    yaml_loader = None
    try:
        import yaml
        yaml_loader = yaml.safe_load
    except Exception:
        yaml_loader = None

    # Helper to resolve environment variables in strings
    env_pattern = re.compile(r'\$\{([^}]+)\}')

    def resolve_env_vars(value):
        if isinstance(value, str):
            def repl(match):
                var = match.group(1)
                return os.getenv(var, '')
            return env_pattern.sub(repl, value)
        return value

    # Recursive traversal to resolve env vars in nested structures
    def traverse_and_resolve(obj):
        if isinstance(obj, dict):
            return {k: traverse_and_resolve(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [traverse_and_resolve(v) for v in obj]
        else:
            return resolve_env_vars(obj)

    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                content = f.read()
        except Exception as e:
            record = logging.LogRecord(
                name='load_configurations',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f'Failed to read file: {e}',
                args=(),
                exc_info=None
            )
            error_records.append(record)
            continue

        # Determine parser based on file extension
        ext = os.path.splitext(filename)[1].lower()
        parsed = None
        try:
            if ext in {'.yaml', '.yml'} and yaml_loader:
                parsed = yaml_loader(content)
            else:
                # Try JSON first
                parsed = json.loads(content)
        except Exception as e:
            record = logging.LogRecord(
                name='load_configurations',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f'Parse error: {e}',
                args=(),
                exc_info=None
            )
            error_records.append(record)
            continue

        # If parsing succeeded but result is None (empty file), treat as empty dict
        if parsed is None:
            parsed = {}

        # Basic validation: must be a dict
        if not isinstance(parsed, dict):
            record = logging.LogRecord(
                name='load_configurations',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f'Configuration is not a dictionary (type: {type(parsed).__name__})',
                args=(),
                exc_info=None
            )
            error_records.append(record)
            continue

        # Apply overrides if provided
        if overrides and isinstance(overrides, dict):
            try:
                parsed.update(overrides)
            except Exception as e:
                record = logging.LogRecord(
                    name='load_configurations',
                    level=logging.ERROR,
                    pathname=filename,
                    lineno=0,
                    msg=f'Failed to apply overrides: {e}',
                    args=(),
                    exc_info=None
                )
                error_records.append(record)
                continue

        # Resolve environment variables if requested
        if resolve_env:
            try:
                parsed = traverse_and_resolve(parsed)
            except Exception as e:
                record = logging.LogRecord(
                    name='load_configurations',
                    level=logging.ERROR,
                    pathname=filename,
                    lineno=0,
                    msg=f'Environment variable resolution error: {e}',
                    args=(),
                    exc_info=None
                )
                error_records.append(record)
                continue

        configs[filename] = parsed

    return configs, error_records

def force_string(obj):
    """
    This function returns the bytes object corresponding to ``obj``
    in case it is a string using UTF-8.
    """
    if isinstance(obj, str):
        try:
            return obj.encode("utf-8")
        except Exception as exc:
            raise ValueError(f"Failed to encode string to UTF-8: {exc}") from exc
    return obj

@classmethod
def protocol_handlers(cls, protocol_version=None):
    """
    Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    # Ensure the class has a mapping of handlers; if not, treat as empty
    handlers_map = getattr(cls, "_protocol_handlers", {})
    if protocol_version is None:
        # Return a shallow copy to prevent accidental mutation
        return dict(handlers_map)

    if not isinstance(protocol_version, tuple):
        raise TypeError("protocol_version must be a tuple")

    # Retrieve the handler for the requested version, if any
    handler = handlers_map.get(protocol_version)
    if handler is None:
        return {}
    return {protocol_version: handler}

