def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    import re
    from typing import Tuple, Set

    if not isinstance(text, str):
        raise TypeError("text must be a string")
    if replacer is not None and not callable(replacer):
        raise TypeError("replacer must be callable")

    # Mark positions that are inside code blocks (fenced or inline)
    skip = [False] * len(text)
    for m in re.finditer(r'```.*?```', text, flags=re.DOTALL):
        for i in range(m.start(), m.end()):
            skip[i] = True
    for m in re.finditer(r'`[^`]*`', text):
        for i in range(m.start(), m.end()):
            skip[i] = True

    tags: Set[str] = set()
    if replacer:
        parts = []
        last = 0
    else:
        parts = None

    for m in re.finditer(r'#\w+', text):
        start, end = m.span()
        # Skip tags that are inside code blocks
        if any(skip[start:end]):
            continue
        tag = m.group()
        tags.add(tag)
        if replacer:
            parts.append(text[last:start])
            replacement = replacer(tag)
            if replacement is None:
                replacement = ""
            parts.append(str(replacement))
            last = end

    if replacer:
        parts.append(text[last:])
        new_text = "".join(parts)
    else:
        new_text = text

    return tags, new_text

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    try:
        if not isinstance(tag, str):
            return False
        tag = tag.strip()
        if not tag:
            return False
        # Optional length constraint (e.g., max 30 characters)
        if len(tag) > 30:
            return False
        # Tag must not start or end with a hyphen
        if tag[0] == '-' or tag[-1] == '-':
            return False
        prev_hyphen = False
        for ch in tag:
            if ch.islower() or ch.isdigit():
                prev_hyphen = False
                continue
            if ch == '-':
                if prev_hyphen:
                    return False  # no consecutive hyphens
                prev_hyphen = True
                continue
            return False  # invalid character
        return True
    except Exception:
        return False

