def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        if not document or not isinstance(document, str):
            return {}

        # Try JSON first
        try:
            import json
            data = json.loads(document)
            if not isinstance(data, dict):
                return {}
            result: Dict = {}
            result['subject'] = data.get('subject')
            result['aliases'] = data.get('aliases', [])
            links = data.get('links', [])
            if isinstance(links, list):
                parsed_links = []
                for link in links:
                    if isinstance(link, dict):
                        l: Dict = {}
                        for key in ('rel', 'type', 'href', 'title'):
                            if key in link:
                                l[key] = link[key]
                        if 'properties' in link and isinstance(link['properties'], dict):
                            l['properties'] = link['properties']
                        parsed_links.append(l)
                result['links'] = parsed_links
            else:
                result['links'] = []
            return result
        except Exception:
            # Not JSON, try XRD
            try:
                import xml.etree.ElementTree as ET
                root = ET.fromstring(document)
                # Namespace handling
                ns = {'xrd': 'http://docs.oasis-open.org/ns/xri/xrd-1.0'}
                def find_with_ns(tag):
                    return root.find(f'{{{ns["xrd"]}}}{tag}') or root.find(tag)
                subject_elem = find_with_ns('Subject')
                subject = subject_elem.text if subject_elem is not None else None
                aliases = [a.text for a in root.findall(f'{{{ns["xrd"]}}}Alias') if a.text]
                if not aliases:
                    aliases = [a.text for a in root.findall('Alias') if a.text]
                links = []
                for link_elem in root.findall(f'{{{ns["xrd"]}}}Link'):
                    l: Dict = {}
                    for attr in ('rel', 'type', 'href', 'title'):
                        val = link_elem.get(attr)
                        if val:
                            l[attr] = val
                    # Properties inside Link
                    props: Dict = {}
                    for prop in link_elem.findall(f'{{{ns["xrd"]}}}Property'):
                        name = prop.get('name')
                        if name:
                            props[name] = prop.text
                    if props:
                        l['properties'] = props
                    if l:
                        links.append(l)
                if not links:
                    for link_elem in root.findall('Link'):
                        l: Dict = {}
                        for attr in ('rel', 'type', 'href', 'title'):
                            val = link_elem.get(attr)
                            if val:
                                l[attr] = val
                        if l:
                            links.append(l)
                result: Dict = {
                    'subject': subject,
                    'aliases': aliases,
                    'links': links
                }
                return result
            except Exception:
                return {}
    except Exception:
        return {}

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    if not host or not isinstance(host, str):
        raise ValueError("host must be a non-empty string")
    host = host.strip()
    if not host.startswith(('http://', 'https://')):
        url = 'https://' + host
    else:
        url = host
    if not url.endswith('/'):
        url += '/'
    url += '.well-known/host-meta'
    urllib_request = __import__('urllib.request')
    urllib_error = __import__('urllib.error')
    try:
        with urllib_request.urlopen(url, timeout=10) as resp:
            code = resp.getcode()
            if code != 200:
                raise ValueError(f"HTTP error {code} retrieving host-meta from {url}")
            data = resp.read()
    except urllib_error.URLError as e:
        raise ValueError(f"Error retrieving host-meta from {url}: {e}") from e
    xml_etree = __import__('xml.etree.ElementTree')
    try:
        root = xml_etree.fromstring(data)
    except xml_etree.ParseError as e:
        raise ValueError(f"Error parsing host-meta XML from {url}: {e}") from e
    return root

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type"""
    import os
    import fnmatch

    # Validate inputs
    if not isinstance(settings_dirs, (list, tuple)):
        raise TypeError("settings_dirs must be a list or tuple of directory paths")
    if spec_option is not None and not isinstance(spec_option, str):
        raise TypeError("spec_option must be a string pattern or None")

    result = []
    for dir_path in settings_dirs:
        if not isinstance(dir_path, str):
            continue  # skip invalid entries
        try:
            if not os.path.isdir(dir_path):
                continue
            for entry in os.listdir(dir_path):
                full_path = os.path.join(dir_path, entry)
                if os.path.isfile(full_path):
                    if spec_option is None or fnmatch.fnmatch(entry, spec_option):
                        result.append(full_path)
        except (OSError, PermissionError):
            # Skip directories that cannot be accessed
            continue
    return result

