    """
    Check if value of choice arguments is one of the available choices.

    :param args: The received arguments. Expected to be a dict or a list of key/value pairs.
    :raises TypeError: If args is not a dict or list of key/value pairs, or if self.choices is not a dict.
    :raises ValueError: If any argument value is not within its allowed choices.
    :return: True if all values are valid.
    """
    # Validate args input
    if args is None:
        raise TypeError("args cannot be None")
    if isinstance(args, list):
        try:
            args = dict(args)
        except Exception as exc:
            raise TypeError("args list must contain key/value pairs") from exc
    if not isinstance(args, dict):
        raise TypeError("args must be a dict or a list of key/value pairs")

    # Retrieve the choices mapping from the instance
    choices = getattr(self, "choices", {})
    if not isinstance(choices, dict):
        raise TypeError("self.choices must be a dict mapping argument names to allowed values")

    # Iterate over provided arguments and validate against allowed choices
    for key, value in args.items():
        # Skip keys that have no defined choices
        if key not in choices:
            continue

        allowed = choices[key]

        # Skip validation if the value is None (often used for optional arguments)
        if value is None:
            continue

        # Determine how to check membership based on the type of allowed
        if isinstance(allowed, (list, set, tuple)):
            if value not in allowed:
                raise ValueError(
                    f"Invalid value for argument '{key}': {value}. "
                    f"Allowed choices: {allowed}"
                )
        elif isinstance(allowed, str):
            if value != allowed:
                raise ValueError(
                    f"Invalid value for argument '{key}': {value}. "
                    f"Allowed choice: {allowed}"
                )
        else:
            # If allowed is a callable or other type, attempt to use it as a validator
            try:
                if not allowed(value):
                    raise ValueError(
                        f"Invalid value for argument '{key}': {value}. "
                        f"Allowed choices: {allowed}"
                    )
            except Exception as exc:
                raise ValueError(
                    f"Invalid value for argument '{key}': {value}. "
                    f"Allowed choices: {allowed}"
                ) from exc

    return True

def validate_min_max_args(self, args):
    """
    Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments. Can be a single value, a list/tuple/set,
                 a dictionary of values, or any iterable of numeric values.
    :return: True if all arguments are within the defined bounds.
    :raises ValueError: If any argument is out of bounds or if min/max are not set.
    :raises TypeError: If an argument is not a numeric type.
    """
    # Retrieve min and max bounds from the instance
    min_val = getattr(self, 'min', None)
    max_val = getattr(self, 'max', None)

    if min_val is None or max_val is None:
        raise ValueError('Minimum and maximum values must be set on the instance.')

    if min_val > max_val:
        raise ValueError('Minimum value cannot be greater than maximum value.')

    if args is None:
        raise ValueError('No arguments provided.')

    # Determine the iterable of values to check
    if isinstance(args, dict):
        values = args.values()
    elif isinstance(args, (list, tuple, set)):
        values = args
    elif isinstance(args, str):
        # Treat a string as a single value
        values = [args]
    else:
        # Try to iterate; if not iterable, treat as single value
        try:
            iter(args)
            values = args
        except TypeError:
            values = [args]

    for val in values:
        if not isinstance(val, (int, float)):
            raise TypeError(f'Argument {val!r} is not a numeric type.')
        if val < min_val or val > max_val:
            raise ValueError(f'Argument {val} out of bounds [{min_val}, {max_val}].')

    return True

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
    """
    Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Basic validation of inputs
    if not isinstance(subcommand, str):
        raise TypeError(f"subcommand must be a string, got {type(subcommand).__name__}")
    if not isinstance(type_name, str):
        raise TypeError(f"type_name must be a string, got {type(type_name).__name__}")
    if not isinstance(option_name, str):
        raise TypeError(f"option_name must be a string, got {type(option_name).__name__}")
    if spec_option is None:
        spec_option = {}
    if not isinstance(spec_option, dict):
        raise TypeError(f"spec_option must be a dict, got {type(spec_option).__name__}")

    # Extract common spec keys with defaults
    expected_type = spec_option.get('type', str)
    choices = spec_option.get('choices')
    required = spec_option.get('required', False)
    default = spec_option.get('default')

    # Ensure expected_type is callable
    if not callable(expected_type):
        raise TypeError(f"spec_option['type'] must be callable, got {type(expected_type).__name__}")

    class ComplexType:
        """A callable that validates and converts a value according to spec_option."""
        def __init__(self, value=None):
            self.value = value

        def __call__(self, value):
            # Handle required
            if required and (value is None or value == ''):
                raise ValueError(f"Option '{option_name}' is required for subcommand '{subcommand}'")
            # Use default if value is None
            if value is None:
                value = default
            # Type conversion
            try:
                converted = expected_type(value)
            except Exception as exc:
                raise ValueError(f"Failed to convert option '{option_name}' value '{value}' "
                                 f"to {expected_type.__name__}: {exc}") from exc
            # Choice validation
            if choices is not None and converted not in choices:
                raise ValueError(f"Option '{option_name}' value '{converted}' not in allowed choices {choices}")
            return converted

        def __repr__(self):
            return f"<ComplexType {type_name} for option '{option_name}'>"

    # Return an instance of the complex type
    return ComplexType()

@staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """
        Extend ``vars_dict`` with ``extra-vars``.

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars (each in the form ``key=value``)
        :return: The updated dictionary (modified in place)
        """
        if vars_dict is None:
            raise TypeError("vars_dict must be a dictionary, got None")
        if not isinstance(vars_dict, dict):
            raise TypeError(f"vars_dict must be a dict, got {type(vars_dict).__name__}")

        if not extra_vars:
            return vars_dict

        # Allow a single string of space-separated key=value pairs
        if isinstance(extra_vars, str):
            extra_vars = extra_vars.split()

        if not isinstance(extra_vars, (list, tuple)):
            raise TypeError(f"extra_vars must be a list or tuple, got {type(extra_vars).__name__}")

        import json

        for var in extra_vars:
            if not isinstance(var, str):
                continue
            if '=' not in var:
                continue
            key, value = var.split('=', 1)
            key = key.strip()
            if not key:
                continue
            value = value.strip()
            # Try to interpret the value as JSON (bool, null, number, list, dict)
            try:
                parsed_value = json.loads(value)
                value = parsed_value
            except Exception:
                # If the value contains commas, split into a list of items
                if ',' in value:
                    parts = [p.strip() for p in value.split(',')]
                    parsed_parts = []
                    for part in parts:
                        try:
                            parsed_parts.append(json.loads(part))
                        except Exception:
                            parsed_parts.append(part)
                    value = parsed_parts
                # Otherwise keep the string as is
            vars_dict[key] = value

        return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import subprocess
    import json
    import os

    # Validate playbook path
    if not os.path.isfile(playbook_path):
        raise FileNotFoundError(f"Playbook '{playbook_path}' does not exist or is not a file")

    # Base command
    cmd = ["ansible-playbook", playbook_path]

    # Verbosity
    if verbose is not None:
        if isinstance(verbose, int):
            if verbose > 0:
                cmd.append("-" + "v" * verbose)
        elif isinstance(verbose, str):
            # Accept strings like 'v', 'vv', etc.
            if all(c == "v" for c in verbose):
                cmd.append("-" + verbose)
        else:
            raise ValueError("verbose must be an int or a string of 'v' characters")

    # Extra vars
    if extra_vars:
        if not isinstance(extra_vars, dict):
            raise TypeError("extra_vars must be a dict")
        try:
            json_str = json.dumps(extra_vars)
        except (TypeError, ValueError) as exc:
            raise ValueError(f"Failed to serialize extra_vars to JSON: {exc}") from exc
        cmd.extend(["--extra-vars", json_str])

    # Additional ansible arguments
    if ansible_args:
        if not isinstance(ansible_args, dict):
            raise TypeError("ansible_args must be a dict")
        for key, value in ansible_args.items():
            # Normalize key to start with '--'
            if not key.startswith("--"):
                key = f"--{key}"
            if isinstance(value, bool):
                if value:
                    cmd.append(key)
                # if False, skip
            elif value is None:
                # Treat None as flag
                cmd.append(key)
            else:
                cmd.extend([key, str(value)])

    # Execute the command
    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            check=False,
        )
    except FileNotFoundError as exc:
        raise RuntimeError("ansible-playbook command not found. Ensure Ansible is installed.") from exc
    except Exception as exc:
        raise RuntimeError(f"Failed to run ansible-playbook: {exc}") from exc

    # Log output if plugin provides logging
    try:
        if hasattr(ir_plugin, "log"):
            ir_plugin.log(result.stdout)
            if result.stderr:
                ir_plugin.log(result.stderr)
    except Exception:
        # If logging fails, ignore
        pass

    # Return exit code
    return result.returncode

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    from pathlib import Path

    def _flatten(d, parent_key=''):
        flat = {}
        for k, v in d.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                flat.update(_flatten(v, new_key))
            else:
                flat[new_key] = v
        return flat

    # Validate input
    if not plugin_dir:
        return {}
    try:
        path = Path(plugin_dir)
    except Exception:
        return {}

    if not path.is_dir():
        return {}

    # Determine spec file
    spec_file = None
    for name in ('plugin.yaml', 'plugin.yml', 'plugin.json'):
        candidate = path / name
        if candidate.is_file():
            spec_file = candidate
            break

    if not spec_file:
        return {}

    # Load spec
    try:
        with spec_file.open('r', encoding='utf-8') as f:
            content = f.read()
    except OSError:
        return {}

    spec = None
    if spec_file.suffix.lower() in {'.yaml', '.yml'}:
        try:
            import yaml
            spec = yaml.safe_load(content)
        except Exception:
            # fallback to json if yaml fails
            try:
                spec = json.loads(content)
            except Exception:
                return {}
    else:
        try:
            spec = json.loads(content)
        except Exception:
            # fallback to yaml if json fails
            try:
                import yaml
                spec = yaml.safe_load(content)
            except Exception:
                return {}

    if not isinstance(spec, dict):
        return {}

    return _flatten(spec)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    import os
    try:
        # Use a common key; treat empty string as undefined
        if not os.environ.get("CONFIG_PATH"):
            # Default to a config file named 'config.yaml' in the current working directory
            default_path = os.path.join(os.getcwd(), "config.yaml")
            os.environ["CONFIG_PATH"] = default_path
    except Exception:
        # Silently ignore any unexpected errors to avoid breaking the caller
        pass
